parameters.jsCode:
// Keep only rows that can actually be fetched: the URL must start with http.
// The Sheets "get" node returns one item per row, keyed by the tab's headers:
// Label | URL | Last Hash | Last Checked | Last Change Note.
// Rows without a usable URL (blank lines, notes, a mistyped address) are
// dropped silently — there is nothing to watch on them.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const url = String(j['URL'] || '').trim();
  if (!url.toLowerCase().startsWith('http')) continue;
  out.push({ json: {
    label: String(j['Label'] || '').trim() || url,
    url: url,
    last_hash: String(j['Last Hash'] || '').trim()
  }});
}
return out;

// Pair each fetched page with its Watch List row by position: the HTTP node
// preserves item order, so item i here belongs to row i of
// 'Keep Watchable Rows'. (If you rename that node, update the name below.)
//
// From the raw HTML we keep only the visible text: script/style blocks are
// removed, every remaining tag is stripped, whitespace is collapsed. That
// text is fingerprinted with a small djb2 hash. Comparing hashes detects
// THAT the visible text changed — it does not extract or compare prices.
const rows = $('Keep Watchable Rows').all();
function djb2(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const out = [];
const pages = $input.all();
for (let i = 0; i < pages.length; i++) {
  const row = (rows[i] && rows[i].json) || {};
  const item = pages[i];
  let html = '';
  if (typeof item.json === 'string') html = item.json;
  else if (item.json) html = item.json.data || item.json.body || item.json.text || '';
  const text = String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const newHash = djb2(text);
  const oldHash = String(row.last_hash || '').trim();
  const firstRun = oldHash === '';
  out.push({ json: {
    label: row.label || row.url || '',
    url: row.url || '',
    old_hash: oldHash,
    new_hash: newHash,
    changed: !firstRun && oldHash !== newHash,
    first_run: firstRun,
    text_sample: text.slice(0, 300)
  }});
}
return out;

parameters.message:
A page on your competitor Watch List changed since the last check.

Competitor / page: {{ $json.label }}
URL: {{ $json.url }}
Checked: {{ $now.toFormat('yyyy-LL-dd HH:mm') }}

Start of the page's visible text as fetched today:
"{{ $json.text_sample }}"

What to do: open the page and compare it with what you remember (or your last screenshot). This workflow detects THAT the visible text changed — it does not extract prices, so it cannot tell you the old vs new price. Banners, dates and rotating offers also change text, so treat this as a prompt to look, not proof of a price move.

The Watch List row is updated with today's fingerprint in this same run, so you will not be alerted about this same change again tomorrow.

— {{ $('CONFIG — Edit Me').first().json.config_business_name }} Competitor Watch
